            <strong>{t(`styleNames.${style}`)}</strong>
            <span style={{ color: "var(--text-secondary-color)" }}>
              {" · "}
              {t(`styleHints.${style}`)}
            </span>
          </figcaption>
        </figure>
      ))}
    </div>
  );
}

